Given two arrays a[] and b[] of size m and n respectively, the task is to determine whether b[] is a subset of a[]. Both arrays are not sorted, and elements are distinct.Examples: Input: a[] = [11, 1, 13, 21, 3, 7], b[] = [11, 3, 7, 1] Output: trueInput: a[]= [1, 2, 3, 4, 5, 6], b = [1, 2, 4] Output: trueInput: a[] = [10, 5, 2, 23, 19], b = [19, 5, 3] Output: falseTry It YourselfTable of Content[Naive approach] Using Nested Loops - O(m*n) Time and O(1) Space[Better Approach] Using Sorting and Two Pointer - O(m log m + n log n) Time and O(1) space[Expected Approach] Using Hashing - O(m + n) Time and O(m) Space[Naive approach] Using Nested Loops - O(m*n) Time and O(1) SpaceThe very basic approach is to use two nested loops, the outer loop picks each element from b[], and the inner loop searches for this element in a[] and check for all elements in b[].
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool isSubset(vector<int> &a, vector<int> &b)
{

    // Iterate over each element in the second array
    int m = a.size(), n = b.size();
    for (int i = 0; i < n; i++)
    {
        bool found = false;

        // Check if the element exists in the first array
        for (int j = 0; j < m; j++)
        {
            if (b[i] == a[j])
            {
                found = true;
                a[j] = -1;
                break;
            }
        }

        // If any element is not found, return false
        if (!found)
            return false;
    }

    // If all elements are found, return true
    return true;
}

int main()
{
    vector<int> a = {11, 1, 13, 21, 3, 7};
    vector<int> b = {11, 3, 7, 1};

    if (isSubset(a, b))
    {
        cout << "true" << endl;
    }
    else
    {
        cout << "false" << endl;
    }

    return 0;
}


