[Better Approach] Using Sorting and Two Pointer - O(m log m + n log n) Time and O(1) spaceSort both arrays and use two pointers to traverse them. If the current element of a[] is smaller, move the pointer in a. If the elements match, move both pointers. If the current element of a[] is greater than b[], then b[j] is missing in a[], so return false.
            C++

    #include <iostream>
using namespace std;

bool isSubset(vector<int>& a, vector<int>& b) {
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    int i = 0, j = 0;
    int m = a.size(), n = b.size();

    while (i < m && j < n) {
        if (a[i] < b[j]) {
            // move in a to catch up
            i++;   
        }
        else if (a[i] == b[j]) {
            i++;
            // matched one element from b
            j++;   
        }
        else {
            // a[i] > b[j] → means b[j] is missing
            return false;
        }
    }

    // all b[] matched
    return (j == n); 
}

int main() {
    vector<int> a = {11, 1, 13, 21, 3, 7};
    vector<int> b = {11, 3, 7, 1};

    if (isSubset(a, b)) cout << "true\n";
    else cout << "false\n";

    return 0;
}


